public class CompressedOopsDiagnostics {
    public static void main(String[] args) {
        // Run with: java -XX:+PrintFlagsFinal -version | grep UseCompressedOops
        // Or inspect via ManagementFactory to see runtime JVM arguments
        String vmArgs = java.lang.management.ManagementFactory
            .getRuntimeMXBean()
            .getInputArguments()
            .toString();

        System.out.println("JVM Arguments: " + vmArgs);
        System.out.println("Max Heap (Bytes): " + Runtime.getRuntime().maxMemory());
    }
}
